<script setup lang="ts">
import { ArrowLeft, Plus, RefreshRight } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'

import { authState } from '@/api/auth'
import { ApiError } from '@/api/http'
import { addPackingBox, cancelPacking, completePacking, deletePackingBox, getPackingDetail, startPacking, updatePackingBox, type PackingAllocation, type PackingBox, type PackingDetail, type PackingStatus } from '@/api/packing'

const route = useRoute(); const router = useRouter(); const detail = ref<PackingDetail | null>(null); const loading = ref(false); const submitting = ref(false); const dialogVisible = ref(false); const editing = ref<PackingBox | null>(null)
const orderId = computed(() => Number(route.params.orderId)); const canManage = computed(() => authState.user?.roles.some(role => ['OWNER', 'PACKING'].includes(role)) ?? false)
const form = reactive({ weightGrams: null as number | null, lengthMm: null as number | null, widthMm: null as number | null, heightMm: null as number | null, note: '', quantities: {} as Record<number, number> })
const statusNames: Record<PackingStatus, string> = { READY: '待开始', DRAFT: '打包中', COMPLETED: '已完成', CANCELED: '已取消' }
const eventNames: Record<string, string> = { STARTED: '开始打包', BOX_ADDED: '新增包装箱', BOX_UPDATED: '更新包装箱', BOX_REMOVED: '删除包装箱', COMPLETED: '完成打包', CANCELED: '取消打包' }
const allocationStatusNames = { RESERVED: '预留中', CONSUMED: '已消耗', RELEASED: '已释放' } as const
async function load() { if (!Number.isInteger(orderId.value) || orderId.value <= 0) return; loading.value = true; try { detail.value = await getPackingDetail(orderId.value) } catch (error) { ElMessage.error(error instanceof ApiError ? error.message : '打包详情加载失败') } finally { loading.value = false } }
async function start() { submitting.value = true; try { await startPacking(orderId.value, '工作台开始打包'); ElMessage.success('已开始打包'); await load() } catch (error) { showError(error, '开始打包失败') } finally { submitting.value = false } }
function openBox(box: PackingBox | null = null) { editing.value = box; Object.assign(form, { weightGrams: box?.weightGrams ?? null, lengthMm: box?.lengthMm ?? null, widthMm: box?.widthMm ?? null, heightMm: box?.heightMm ?? null, note: box?.note ?? '', quantities: {} as Record<number, number> }); for (const item of box?.items ?? []) form.quantities[item.allocationId] = item.quantity; dialogVisible.value = true }
function remaining(allocation: PackingAllocation) { const used = (detail.value?.boxes ?? []).filter(box => box.id !== editing.value?.id).flatMap(box => box.items).filter(item => item.allocationId === allocation.allocationId).reduce((sum, item) => sum + item.quantity, 0); return allocation.quantity - used }
async function saveBox() { if (!detail.value?.taskId) return; const items = detail.value.allocations.map(item => ({ allocationId: item.allocationId, quantity: Number(form.quantities[item.allocationId] ?? 0) })).filter(item => item.quantity > 0); if (!items.length) { ElMessage.warning('请至少填写一种商品的装箱数量'); return } const dimensions = [form.lengthMm, form.widthMm, form.heightMm]; if (dimensions.some(Boolean) && dimensions.some(value => !value)) { ElMessage.warning('长宽高需要同时填写'); return } submitting.value = true; try { const input = { weightGrams: form.weightGrams, lengthMm: form.lengthMm, widthMm: form.widthMm, heightMm: form.heightMm, note: form.note.trim(), version: detail.value.version, items }; if (editing.value) await updatePackingBox(detail.value.taskId, editing.value.id, input); else await addPackingBox(detail.value.taskId, input); dialogVisible.value = false; ElMessage.success(editing.value ? '包装箱已更新' : '包装箱已添加'); await load() } catch (error) { showError(error, '保存包装箱失败') } finally { submitting.value = false } }
async function removeBox(box: PackingBox) { if (!detail.value?.taskId) return; await ElMessageBox.confirm(`确认删除包装箱 ${box.boxNo}？`, '删除包装箱', { type: 'warning' }); submitting.value = true; try { await deletePackingBox(detail.value.taskId, box.id, detail.value.version); ElMessage.success('包装箱已删除'); await load() } catch (error) { showError(error, '删除包装箱失败') } finally { submitting.value = false } }
async function complete() { if (!detail.value?.taskId) return; await ElMessageBox.confirm('完成后将扣减全部库存预留，且第一阶段不支持撤销。确认完成打包？', '完成打包', { type: 'warning' }); submitting.value = true; try { await completePacking(detail.value.taskId, detail.value.version); ElMessage.success('订单打包完成，库存已扣减'); await load() } catch (error) { showError(error, '完成打包失败') } finally { submitting.value = false } }
async function cancel() { if (!detail.value?.taskId) return; const result = await ElMessageBox.prompt('请输入取消原因', '取消打包任务', { inputPattern: /\S+/, inputErrorMessage: '取消原因不能为空' }); submitting.value = true; try { await cancelPacking(detail.value.taskId, detail.value.version, result.value.trim()); ElMessage.success('打包任务已取消'); await load() } catch (error) { showError(error, '取消打包失败') } finally { submitting.value = false } }
function showError(error: unknown, fallback: string) { ElMessage.error(error instanceof ApiError ? error.message : fallback) }
function formatDate(value: string | null) { return value ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—' }
onMounted(load)
</script>

<template>
  <section class="detail-page"><div class="top-actions"><el-button text :icon="ArrowLeft" @click="router.push('/packing')">返回打包工作台</el-button><el-button :icon="RefreshRight" :loading="loading" @click="load">刷新</el-button></div>
    <template v-if="detail"><section class="hero"><div><span class="kicker">PACKING TASK</span><h2>{{ detail.orderNo }}</h2><p>{{ detail.storeName }} · {{ detail.taskNo || '尚未创建打包任务' }}</p></div><div class="hero-actions"><span class="status-pill" :class="detail.status.toLowerCase()">{{ statusNames[detail.status] }}</span><el-button v-if="canManage && detail.availableActions.includes('START')" type="primary" :loading="submitting" @click="start">开始打包</el-button><template v-if="canManage && detail.status === 'DRAFT'"><el-button type="primary" :icon="Plus" @click="openBox()">新增包装箱</el-button><el-button type="success" :loading="submitting" @click="complete">完成打包</el-button><el-button type="danger" plain :loading="submitting" @click="cancel">取消任务</el-button></template></div></section>
      <section class="summary"><article><small>预留批次</small><strong>{{ detail.allocations.length }}</strong></article><article><small>订单数量</small><strong>{{ detail.allocations.reduce((sum, item) => sum + item.quantity, 0) }}</strong></article><article><small>包装箱</small><strong>{{ detail.boxes.length }}</strong></article><article><small>要求发货</small><span>{{ formatDate(detail.requestedShipAt) }}</span></article></section>
      <div class="grid"><main><section class="panel"><div class="panel-heading"><div><span class="kicker">BOXES</span><h3>包装箱</h3></div><span>{{ detail.boxes.length }} 箱</span></div><div v-if="detail.boxes.length" class="box-list"><article v-for="box in detail.boxes" :key="box.id" class="box-card"><header><div><strong>{{ box.boxNo }}</strong><small>{{ box.weightGrams ? `${box.weightGrams}g` : '未称重' }} · {{ box.lengthMm ? `${box.lengthMm}×${box.widthMm}×${box.heightMm}mm` : '未量尺寸' }}</small></div><div v-if="detail.status === 'DRAFT' && canManage"><el-button link type="primary" @click="openBox(box)">编辑</el-button><el-button link type="danger" @click="removeBox(box)">删除</el-button></div></header><el-table :data="box.items" size="small"><el-table-column prop="productName" label="商品" min-width="180" /><el-table-column prop="lotNo" label="库存批次" min-width="150" /><el-table-column prop="quantity" label="数量" width="80" /></el-table><p v-if="box.note">{{ box.note }}</p></article></div><el-empty v-else description="尚未添加包装箱" :image-size="72" /></section>
        <section class="panel"><div class="panel-heading"><div><span class="kicker">RESERVATIONS</span><h3>库存预留</h3></div></div><el-table :data="detail.allocations"><el-table-column label="商品" min-width="190"><template #default="{ row }: { row: PackingAllocation }">{{ row.productName }}{{ row.variantName ? ` · ${row.variantName}` : '' }}</template></el-table-column><el-table-column prop="lotNo" label="库存批次" min-width="150" /><el-table-column prop="allocationNo" label="分配单号" min-width="170" /><el-table-column prop="quantity" label="数量" width="80" /><el-table-column label="状态" width="110"><template #default="{ row }: { row: PackingAllocation }">{{ allocationStatusNames[row.status] }}</template></el-table-column></el-table></section></main>
        <aside><section class="panel"><div class="panel-heading"><div><span class="kicker">EVENTS</span><h3>操作记录</h3></div></div><el-timeline class="timeline"><el-timeline-item v-for="event in detail.events" :key="event.id" :timestamp="formatDate(event.occurredAt)"><strong>{{ eventNames[event.eventType] || event.eventType }}</strong><p>{{ event.operatorName }}{{ event.remark ? ` · ${event.remark}` : '' }}</p></el-timeline-item></el-timeline><el-empty v-if="!detail.events.length" description="暂无操作记录" :image-size="64" /></section></aside></div>
    </template><el-empty v-else-if="!loading" description="打包详情不存在" /><div v-else class="loading" v-loading="loading" />
    <el-dialog v-model="dialogVisible" :title="editing ? '编辑包装箱' : '新增包装箱'" width="min(720px, 94vw)"><el-form label-position="top"><div class="measure-grid"><el-form-item label="重量（克）"><el-input-number v-model="form.weightGrams" :min="1" :controls="false" /></el-form-item><el-form-item label="长（毫米）"><el-input-number v-model="form.lengthMm" :min="1" :controls="false" /></el-form-item><el-form-item label="宽（毫米）"><el-input-number v-model="form.widthMm" :min="1" :controls="false" /></el-form-item><el-form-item label="高（毫米）"><el-input-number v-model="form.heightMm" :min="1" :controls="false" /></el-form-item></div><el-divider content-position="left">箱内商品</el-divider><div class="allocation-inputs"><div v-for="item in detail?.allocations ?? []" :key="item.allocationId"><span><strong>{{ item.productName }}</strong><small>{{ item.lotNo }} · 最多 {{ remaining(item) }} 件</small></span><el-input-number v-model="form.quantities[item.allocationId]" :min="0" :max="remaining(item)" :controls="false" /></div></div><el-form-item label="备注"><el-input v-model="form.note" type="textarea" :rows="2" maxlength="500" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" :loading="submitting" @click="saveBox">保存包装箱</el-button></template></el-dialog>
  </section>
</template>

<style scoped>
.status-pill{display:inline-flex;align-items:center;justify-content:center;padding:6px 11px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap}.status-pill.ready{color:#275fa6;background:#eaf2fc}.status-pill.draft{color:#9a5a0a;background:#fff2dc}.status-pill.completed{color:#16775b;background:#e7f6f0}.status-pill.canceled{color:#68747b;background:#edf1f2}
.detail-page{display:grid;gap:18px}.top-actions,.hero,.hero-actions,.panel-heading,.box-card header{display:flex;align-items:center;justify-content:space-between;gap:16px}.kicker{color:var(--erp-accent);font-size:10px;font-weight:800;letter-spacing:.16em}.hero,.summary,.panel{border:1px solid var(--erp-border);border-radius:var(--erp-radius);background:var(--erp-surface);box-shadow:0 8px 24px rgb(28 55 49 / 5%)}.hero{padding:24px 28px;border-left:4px solid var(--erp-primary)}.hero h2{margin:2px 0}.hero p{margin:0;color:var(--erp-text-muted)}.hero-actions{flex-wrap:wrap;justify-content:flex-end}.summary{display:grid;grid-template-columns:repeat(4,1fr);overflow:hidden}.summary article{display:grid;gap:4px;padding:18px 20px;border-right:1px solid var(--erp-border)}.summary article:last-child{border:0}.summary small{color:var(--erp-text-muted)}.summary strong{font-size:24px}.grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px;align-items:start}.grid main{display:grid;gap:18px}.panel{overflow:hidden}.panel-heading{padding:18px 20px;border-bottom:1px solid var(--erp-border)}.panel-heading h3{margin:1px 0}.panel-heading>span{color:var(--erp-text-muted)}.box-list{display:grid;gap:14px;padding:16px}.box-card{overflow:hidden;border:1px solid var(--erp-border);border-radius:10px}.box-card header{padding:13px 15px;background:#f7faf9}.box-card header>div:first-child{display:grid;gap:2px}.box-card small,.box-card p,.timeline p{margin:0;color:var(--erp-text-muted);font-size:12px}.box-card>p{padding:10px 15px}.timeline{padding:22px 20px 4px}.measure-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.el-input-number{width:100%}.allocation-inputs{display:grid;gap:8px;margin-bottom:18px}.allocation-inputs>div{display:grid;grid-template-columns:minmax(0,1fr) 130px;align-items:center;gap:16px;padding:10px 12px;border:1px solid var(--erp-border);border-radius:8px}.allocation-inputs span{display:grid;gap:2px}.allocation-inputs small{color:var(--erp-text-muted)}.loading{min-height:320px}@media(max-width:980px){.grid{grid-template-columns:1fr}.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.hero{align-items:flex-start;flex-direction:column}.hero-actions{justify-content:flex-start}.measure-grid{grid-template-columns:repeat(2,1fr)}}
</style>

